CREATE TABLE IF NOT EXISTS forge_jobs(id text PRIMARY KEY,project_id text REFERENCES projects(id),episode_id text REFERENCES episodes(id),tenant_id text REFERENCES tenants(id),kind text NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'QUEUED',priority integer NOT NULL DEFAULT 100,attempts integer NOT NULL DEFAULT 0,max_attempts integer NOT NULL DEFAULT 3,available_at timestamptz NOT NULL DEFAULT now(),leased_until timestamptz,worker_id text,result jsonb,error jsonb,idempotency_key text NOT NULL UNIQUE,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),depends_on_job_id text REFERENCES forge_jobs(id),trace_id text,correlation_id text,cancellation_requested_at timestamptz,dispatch_generation bigint NOT NULL DEFAULT 0,dispatch_token text,timeout_at timestamptz,execution_region text NOT NULL DEFAULT 'primary',routing_epoch bigint NOT NULL DEFAULT 1,fencing_token bigint NOT NULL DEFAULT 1,residency_block_reason text);
CREATE INDEX IF NOT EXISTS forge_jobs_claim_idx ON forge_jobs(status,available_at,priority,created_at);
CREATE INDEX IF NOT EXISTS forge_jobs_episode_idx ON forge_jobs(episode_id,created_at DESC);
CREATE TABLE IF NOT EXISTS forge_outbox(id bigserial PRIMARY KEY,topic text NOT NULL,aggregate_type text NOT NULL,aggregate_id text NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,project_id text REFERENCES projects(id),published_at timestamptz,attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_idempotency_keys(key text PRIMARY KEY,actor text NOT NULL,request_hash char(64) NOT NULL,response_status integer,response_body jsonb,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS forge_concurrency_events(id bigserial PRIMARY KEY,event_type text NOT NULL,project_id text REFERENCES projects(id),episode_id text REFERENCES episodes(id),job_id text REFERENCES forge_jobs(id),version_id text REFERENCES version_records(id),actor text,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_execution_runs(id text PRIMARY KEY,job_id text NOT NULL REFERENCES forge_jobs(id) ON DELETE CASCADE,attempt integer NOT NULL,backend text NOT NULL,worker_type text NOT NULL,workflow_name text NOT NULL,correlation_id text NOT NULL UNIQUE,idempotency_key text NOT NULL,status text NOT NULL DEFAULT 'DISPATCHING',github_run_id text,github_run_attempt integer,workflow_ref text,runner_profile text,input_manifest_uri text,output_manifest_uri text,dispatched_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz,last_reconciled_at timestamptz,heartbeat_at timestamptz,timeout_at timestamptz,failure_code text,failure_message text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,attempt),UNIQUE(job_id,idempotency_key));
CREATE TABLE IF NOT EXISTS channels(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),name text NOT NULL,destination text NOT NULL DEFAULT 'youtube',config jsonb NOT NULL DEFAULT '{}'::jsonb,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,name));
CREATE TABLE IF NOT EXISTS style_profiles(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),name text NOT NULL,profile jsonb NOT NULL DEFAULT '{}'::jsonb,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,name));
CREATE TABLE IF NOT EXISTS research_packages(id text PRIMARY KEY,episode_id text NOT NULL REFERENCES episodes(id),version_id text NOT NULL REFERENCES version_records(id),status text NOT NULL DEFAULT 'DRAFT',notes text NOT NULL DEFAULT '',created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS research_sources(id text PRIMARY KEY,package_id text NOT NULL REFERENCES research_packages(id),url text NOT NULL,title text NOT NULL DEFAULT '',publisher text NOT NULL DEFAULT '',published_at timestamptz,retrieved_at timestamptz NOT NULL DEFAULT now(),content_hash char(64),metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS research_claims(id text PRIMARY KEY,package_id text NOT NULL REFERENCES research_packages(id),claim text NOT NULL,status text NOT NULL DEFAULT 'DISCOVERED',source_ids jsonb NOT NULL DEFAULT '[]'::jsonb,metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS timeline_snapshots(id text PRIMARY KEY,episode_id text NOT NULL REFERENCES episodes(id),version_id text NOT NULL REFERENCES version_records(id),timeline jsonb NOT NULL,duration_seconds numeric(12,3) NOT NULL,content_hash char(64) NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS storage_objects(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),artifact_id text REFERENCES artifacts(id),uri text NOT NULL,storage_key text,content_hash char(64),media_type text,size_bytes bigint,retention_class text NOT NULL DEFAULT 'HOT',expires_at timestamptz,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS publish_runs(id text PRIMARY KEY,episode_id text NOT NULL REFERENCES episodes(id),render_artifact_id text NOT NULL REFERENCES artifacts(id),render_version_id text NOT NULL REFERENCES version_records(id),destination text NOT NULL DEFAULT 'youtube',metadata jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'QUEUED',external_id text,external_url text,attempt integer NOT NULL DEFAULT 1,error jsonb,idempotency_key text NOT NULL UNIQUE,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz,lease_token text,lease_until timestamptz);
CREATE TABLE IF NOT EXISTS caption_runs(id text PRIMARY KEY,episode_id text NOT NULL REFERENCES episodes(id),transcript_artifact_id text NOT NULL REFERENCES artifacts(id),transcript_version_id text NOT NULL REFERENCES version_records(id),timeline_artifact_id text REFERENCES artifacts(id),timeline_version_id text REFERENCES version_records(id),caption_version_id text REFERENCES version_records(id),status text NOT NULL,idempotency_key text NOT NULL UNIQUE,checksums jsonb NOT NULL DEFAULT '{}'::jsonb,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,error jsonb,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz);
CREATE TABLE IF NOT EXISTS asset_ingestions(id text PRIMARY KEY,episode_id text NOT NULL REFERENCES episodes(id),project_id text NOT NULL REFERENCES projects(id),source_checksum char(64) NOT NULL,source_kind text NOT NULL,source_artifact_id text REFERENCES artifacts(id),source_version_id text,provenance_fingerprint char(64) NOT NULL,status text NOT NULL DEFAULT 'PROCESSING',artifact_id text REFERENCES artifacts(id),version_id text REFERENCES version_records(id),diagnostics jsonb NOT NULL DEFAULT '[]'::jsonb,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS episode_workflows(id text PRIMARY KEY,episode_id text NOT NULL REFERENCES episodes(id),project_id text NOT NULL REFERENCES projects(id),brief text NOT NULL,requested_stages jsonb NOT NULL,status text NOT NULL DEFAULT 'QUEUED',current_stage text,last_safe_stage text,failure_stage text,failure jsonb,idempotency_key text NOT NULL UNIQUE,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS episode_workflow_stages(workflow_id text NOT NULL REFERENCES episode_workflows(id) ON DELETE CASCADE,stage text NOT NULL,status text NOT NULL DEFAULT 'BLOCKED',job_id text REFERENCES forge_jobs(id),input_version_ids jsonb NOT NULL DEFAULT '[]'::jsonb,output_version_ids jsonb NOT NULL DEFAULT '[]'::jsonb,output_artifact_ids jsonb NOT NULL DEFAULT '[]'::jsonb,error jsonb,started_at timestamptz,finished_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workflow_id,stage));
